/** Registry by character slug. Add rex / reyes / perez here (docs/legal/textos/03 B2, B3). */
export const PRELUDES: Record<string, Record<TextLocale, PreludeTexts>> = { santa: SANTA };

export function getPreludeTexts(character: string, locale: TextLocale): PreludeTexts {
  const byLocale = PRELUDES[character];
  if (!byLocale) throw new Error(`No prelude defined for character "${character}" (see docs/legal/textos/03)`);
  return byLocale[locale];
}

/** Fills {{MARCA}} and {{NOMBRE_NIÑO}} in every text. */
export function renderPrelude(texts: PreludeTexts, vars: { brand: string; childName: string }): PreludeTexts {
  const v = { MARCA: vars.brand, "NOMBRE_NIÑO": vars.childName };
  return {
    id: texts.id,
    main: fill(texts.main, v),
    repeat: fill(texts.repeat, v),
    handoffRepeat: fill(texts.handoffRepeat, v),
    handoff: fill(texts.handoff, v),
    optout: fill(texts.optout, v),
    noResponse: fill(texts.noResponse, v),
    pressOne: fill(texts.pressOne, v),
    firstLine: fill(texts.firstLine, v),
    closing: fill(texts.closing, v),
  };
}
